import 'package:drift/native.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mirai_cook/data/db/app_database.dart';

void main() {
  // Covers: DATA-1, DATA-9
  // The database produced by the migration strategy must match the schema
  // declared in code. Step-by-step migration tests against the exported
  // schemas in drift_schemas/ are generated by
  // `dart run drift_dev make-migrations` once there are 2+ versions.
  test('migrated schema matches the declared schema', () async {
    final db = AppDatabase(NativeDatabase.memory());
    addTearDown(db.close);
    await db.validateDatabaseSchema();
  });
}
